"use strict";(self.webpackChunkserenity_js_org=self.webpackChunkserenity_js_org||[]).push([[7443],{28453:(e,t,i)=>{i.d(t,{R:()=>r,x:()=>o});var a=i(96540);const n={},s=a.createContext(n);function r(e){const t=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),a.createElement(s.Provider,{value:t},e.children)}},86542:e=>{e.exports=JSON.parse('{"permalink":"/blog/code-was-never-the-hard-part","editUrl":"https://github.com/serenity-js/serenity-js.org/tree/main/src/blog/2026-06-05-code-was-never-the-hard-part/index.mdx","source":"@site/src/blog/2026-06-05-code-was-never-the-hard-part/index.mdx","title":"Code was never the hard part","description":"Jan Graefe recently published an open letter in response to the updated Getting Started guides on serenity-js.org. His letter touches on something that\'s been central to the Screenplay Pattern since 2007 \u2014 and that I\'ve been working on since joining the effort in 2013: the idea that test automation should express intent, not implementation.","date":"2026-06-05T00:00:00.000Z","tags":[{"inline":true,"label":"core","permalink":"/blog/tags/core"},{"inline":true,"label":"open-source","permalink":"/blog/tags/open-source"},{"inline":true,"label":"web","permalink":"/blog/tags/web"},{"inline":true,"label":"playwright-test","permalink":"/blog/tags/playwright-test"}],"readingTime":5.58,"hasTruncateMarker":true,"authors":[{"name":"Jan Molak","url":"https://github.com/jan-molak","imageURL":"https://github.com/jan-molak.png","key":"jan-molak","page":null}],"frontMatter":{"slug":"code-was-never-the-hard-part","title":"Code was never the hard part","authors":["jan-molak"],"tags":["core","open-source","web","playwright-test"],"date":"2026-06-05T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"Introducing the Serenity/JS HTML Reporter","permalink":"/blog/html-reporter"},"nextItem":{"title":"Serenity/JS 3.43: Testing Electron Apps","permalink":"/blog/support-for-electron-apps"}}')},90618:(e,t,i)=>{i.r(t),i.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>a,toc:()=>d});var a=i(86542),n=i(74848),s=i(28453);const r={slug:"code-was-never-the-hard-part",title:"Code was never the hard part",authors:["jan-molak"],tags:["core","open-source","web","playwright-test"],date:new Date("2026-06-05T00:00:00.000Z")},o="Code Was Never the Hard Part",l={authorsImageUrls:[void 0]},d=[{value:"The silver bullet cycle",id:"the-silver-bullet-cycle",level:2},{value:"Why now?",id:"why-now",level:2},{value:"Strategy without architecture is a daydream",id:"strategy-without-architecture-is-a-daydream",level:2},{value:"Progressive adoption",id:"progressive-adoption",level:2},{value:"Code still matters",id:"code-still-matters",level:2},{value:"Architecture as guardrail",id:"architecture-as-guardrail",level:2},{value:"The fundamentals always mattered",id:"the-fundamentals-always-mattered",level:2}];function h(e){const t={a:"a",blockquote:"blockquote",code:"code",em:"em",h2:"h2",img:"img",li:"li",p:"p",ul:"ul",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsxs)(t.p,{children:["Jan Graefe recently published ",(0,n.jsx)(t.a,{href:"https://www.pilot-period.org/serenity-js-open-letter/",children:"an open letter"})," in response to the updated ",(0,n.jsx)(t.a,{href:"/getting-started/",children:"Getting Started guides"})," on serenity-js.org. His letter touches on something that's been central to the ",(0,n.jsx)(t.a,{href:"/handbook/design/screenplay-pattern/",children:"Screenplay Pattern"})," since 2007 \u2014 and that I've been working on since ",(0,n.jsx)(t.a,{href:"/handbook/design/screenplay-pattern/#history-of-the-screenplay-pattern",children:"joining the effort in 2013"}),": the idea that test automation should express intent, not implementation."]}),"\n",(0,n.jsx)(t.p,{children:"I'd like to respond publicly because the ideas Graefe raises deserve a wider conversation."}),"\n","\n",(0,n.jsx)(t.h2,{id:"the-silver-bullet-cycle",children:"The silver bullet cycle"}),"\n",(0,n.jsx)(t.p,{children:"Our industry has a pattern of chasing tools. Selenium, then Cypress, then Playwright. No-code, low-code, AI. Each new arrival promises to solve the test automation problem once and for all."}),"\n",(0,n.jsx)(t.p,{children:"None of them do \u2014 because the hard part was never the code."}),"\n",(0,n.jsx)(t.p,{children:"The hard part is understanding the purpose the system needs to serve, the audience it needs to support, and the goals it needs to help them accomplish. These are difficult things to get right. They require engineers to have a deep understanding of the business domain and their customers. Chasing the next tool is much easier than facing that challenge."}),"\n",(0,n.jsx)(t.p,{children:"Graefe captures this well:"}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"[Serenity/JS's] value is that it encourages teams to think about behaviour, intent, and outcomes. It helps automation express what users are trying to achieve rather than simply documenting which buttons were clicked."}),"\n"]}),"\n",(0,n.jsxs)(t.p,{children:["When you define a Task called ",(0,n.jsx)(t.code,{children:"ScheduleAppointment.with(doctor).at(time)"}),", you're making a design decision. You're naming a business capability and separating it from the mechanics of filling in forms. That separation is what makes the test meaningful six months later when the UI has changed but the business process hasn't."]}),"\n",(0,n.jsxs)(t.p,{children:["This isn't a new idea. It's what the Screenplay Pattern has been about since Antony Marcano first demonstrated the ",(0,n.jsx)(t.a,{href:"/handbook/design/screenplay-pattern/#history-of-the-screenplay-pattern",children:'"Roles, Goals, Tasks, Actions"'})," model almost twenty years ago. What's changed is that the industry may finally be ready to hear it."]}),"\n",(0,n.jsx)(t.h2,{id:"why-now",children:"Why now?"}),"\n",(0,n.jsx)(t.p,{children:"The Screenplay Pattern always required a lot from the people adopting it. Understanding the business domain. Being open to collaboration across roles. Familiarity with Domain-Driven Design (DDD). Having enough software engineering experience to put all of it into practice. That was a lot to ask \u2014 and for many teams, it was too much at once."}),"\n",(0,n.jsx)(t.p,{children:'AI changed the equation. Not because it made the design thinking easier \u2014 it didn\'t. But it made the code generation part trivial. When producing test code is no longer the bottleneck, people are freed up to think about design and architecture. They still need the skills, and they still need a north star to aim for. But the gap between "I understand what good looks like" and "I can actually build it" is finally closing.'}),"\n",(0,n.jsx)(t.h2,{id:"strategy-without-architecture-is-a-daydream",children:"Strategy without architecture is a daydream"}),"\n",(0,n.jsx)(t.p,{children:"Graefe writes:"}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"But the best tools amplify a good strategy rather than compensate for the lack of one."}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"I'd go further: strategy and architecture are co-dependent. You can't have a strategy without something to express it in. A test strategy that lives only in a wiki page or a presentation deck isn't a strategy \u2014 it's an aspiration."}),"\n",(0,n.jsxs)(t.p,{children:["The Screenplay Pattern isn't a tool you pick after deciding your strategy. It ",(0,n.jsx)(t.em,{children:"is"})," the expression of a strategy. When the framework requires you to name a Task before you can use it, that's not ceremony \u2014 it's forcing you to articulate what you're doing in business language before you automate it. When it separates Abilities from Interactions, it's encoding the principle that your test logic shouldn't be coupled to a specific interface driver."]}),"\n",(0,n.jsx)(t.p,{children:"The architecture makes certain strategies natural and others inconvenient. That's by design."}),"\n",(0,n.jsx)(t.h2,{id:"progressive-adoption",children:"Progressive adoption"}),"\n",(0,n.jsx)(t.p,{children:'Graefe notes how the updated site "meets people where they are." This reflects something I\'ve observed over the past two decades working with teams.'}),"\n",(0,n.jsx)(t.p,{children:"Nobody commits to a new way of working because a website or a blog post told them to. They commit when they've hit a real problem, recognised what's holding them back, and experienced firsthand how a better approach helps them move past it. The adoption model exists to let teams prove the value of each layer to themselves:"}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsx)(t.li,{children:"Start with reporting \u2014 you see what your tests cover without changing them."}),"\n",(0,n.jsx)(t.li,{children:"Add Screenplay interactions \u2014 failures become comprehensible because every step has a name."}),"\n",(0,n.jsxs)(t.li,{children:["Adopt full Screenplay \u2014 composable Tasks, ",(0,n.jsx)(t.a,{href:"/handbook/test-runners/playwright-test/multi-actor-scenarios/",children:"multi-actor scenarios"})," and ",(0,n.jsx)(t.a,{href:"/handbook/web-testing/blended-testing/",children:"blended testing"})," become natural."]}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"Each level makes the value of the next one obvious."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.img,{alt:"Levels of Serenity/JS adoption: from your existing tests through reporting, hybrid Screenplay, to the full Screenplay Pattern",src:i(96824).A+"",width:"800",height:"480"})}),"\n",(0,n.jsx)(t.h2,{id:"code-still-matters",children:"Code still matters"}),"\n",(0,n.jsx)(t.p,{children:'Graefe writes that "the value of testing has never been in writing code." This is a popular sentiment, and I understand the spirit \u2014 the value lies in the thinking, the risk analysis, the understanding of what matters.'}),"\n",(0,n.jsxs)(t.p,{children:["But I'd push back, gently. The value of testing has ",(0,n.jsx)(t.em,{children:"always"})," been partly in the code \u2014 specifically in how well that code expresses intent. Poorly written test code doesn't just fail to communicate risk; it actively obscures it. When a test fails and the report shows ",(0,n.jsx)(t.code,{children:"locator('[data-test=\"confirm-appointment\"]') timed out"}),", you know ",(0,n.jsx)(t.em,{children:"something"})," broke but not ",(0,n.jsx)(t.em,{children:"what"})," the user was trying to accomplish."]}),"\n",(0,n.jsxs)(t.p,{children:["Behaviour-Driven Development, Domain-Driven Design, and the Screenplay Pattern have never said \"code doesn't matter.\" They've said: code should express business meaning. The code ",(0,n.jsx)(t.em,{children:"is"})," the thinking, made executable."]}),"\n",(0,n.jsx)(t.h2,{id:"architecture-as-guardrail",children:"Architecture as guardrail"}),"\n",(0,n.jsx)(t.p,{children:"An AI can generate hundreds of flat Playwright scripts in minutes. Debugging, maintaining, and explaining those scripts to a stakeholder six months later is a different problem entirely."}),"\n",(0,n.jsxs)(t.p,{children:["The Screenplay Pattern doesn't just encourage better thinking \u2014 it ",(0,n.jsx)(t.em,{children:"constrains"})," the output. When an AI generates into a Screenplay-based codebase, the framework's structure forces it to produce named ",(0,n.jsx)(t.a,{href:"/handbook/design/screenplay-pattern/#the-five-elements-of-the-screenplay-pattern",children:"Tasks, explicit Interactions, and declared Abilities"}),". The architecture acts as a guardrail: what comes out is maintainable and intention-revealing, not just syntactically valid."]}),"\n",(0,n.jsx)(t.p,{children:"Structure is what makes the difference between test code that works today and a test system that scales."}),"\n",(0,n.jsx)(t.h2,{id:"the-fundamentals-always-mattered",children:"The fundamentals always mattered"}),"\n",(0,n.jsx)(t.p,{children:"BDD, DDD, intent over implementation \u2014 these ideas have been around for decades. They've always mattered. The industry just wasn't ready to pay the cost of learning them, because the immediate pain of bad test architecture was always one tool migration away from being someone else's problem."}),"\n",(0,n.jsx)(t.p,{children:"That's changing. AI made the code cheap. Architecture and design thinking are what's left. The fundamentals were never optional \u2014 they just seemed optional when there was always a new tool to chase."}),"\n",(0,n.jsx)(t.p,{children:"This is what the Serenity/JS community has been working towards. Not a better way to click buttons, but a better way to express what our systems are supposed to do and verify that they do it."}),"\n",(0,n.jsx)(t.p,{children:"Thank you, Jan Graefe. Letters like yours are what keep an open-source project honest."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(h,{...e})}):h(e)}},96824:(e,t,i)=>{i.d(t,{A:()=>a});const a="data:image/svg+xml;base64,"}}]);